<script lang="ts">
 import {untrack,onMount} from 'svelte';
 let {value,content}:{value:{id?:string;name:string;description:string;cover?:string|null;status:string;archived:boolean;members:string[]};content:{id:string;title:string}[]}=$props();
 let ready=$state(false);onMount(()=>{ready=true;});
 let fields=$state(untrack(()=>({...value})));
 let members=$state(untrack(()=>[...value.members]));let selection=$state('');
 function move(index:number,direction:number){const next=[...members];[next[index],next[index+direction]]=[next[index+direction],next[index]];members=next;}
</script>
<form method="post"><fieldset disabled={!ready} class="editor"><legend>系列设置</legend>{#if value.id}<input type="hidden" name="id" value={value.id}/>{/if}<label>系列名称<input name="name" bind:value={fields.name} maxlength="100" required/></label><label>简介<textarea name="description" maxlength="2000" bind:value={fields.description}></textarea></label><label>封面媒体键（可选）<input name="cover" bind:value={fields.cover}/></label><label>公开状态<select name="status" bind:value={fields.status}><option value="draft">草稿，仅自己可见</option><option value="public">公开，公开成员可被阅读</option></select></label><label class="check"><input type="checkbox" name="archived" value="yes" bind:checked={fields.archived}/>归档系列（仍可公开阅读，退出主动推荐）</label>
<fieldset><legend>系列成员顺序</legend><ol>{#each members as id,index}<li><input type="hidden" name="member" value={id}/><span>{content.find(item=>item.id===id)?.title??id}</span><button type="button" disabled={index===0} onclick={()=>move(index,-1)} aria-label={`上移 ${content.find(item=>item.id===id)?.title??id}`}>上移</button><button type="button" disabled={index===members.length-1} onclick={()=>move(index,1)} aria-label={`下移 ${content.find(item=>item.id===id)?.title??id}`}>下移</button><button type="button" onclick={()=>members=members.filter(x=>x!==id)}>移出系列</button></li>{/each}</ol><label>添加文章或笔记<select aria-label="添加文章或笔记" bind:value={selection}><option value="">请选择</option>{#each content.filter(item=>!members.includes(item.id)) as item}<option value={item.id}>{item.title}</option>{/each}</select></label><button type="button" disabled={!selection} onclick={()=>{members=[...members,selection];selection='';}}>添加成员</button></fieldset><p>只有点击保存后才生效；移出系列不会删除或撤回内容。</p><button>保存系列</button></fieldset></form>
<style>form{padding:24px;border:1px solid var(--line);border-radius:16px;margin-block:24px}.editor{border:0;padding:0}fieldset{border:1px solid var(--line);min-width:0}li{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding-block:8px}li span{flex:1;min-width:120px;overflow-wrap:anywhere}ol{padding:0}</style>
